"use client";
import React, { useEffect } from "react";
import Script from "next/script";

// Import existing component
import ProGran from "../../src/components/Products/progran";

const softwareApplicationSchema = {
  "@context": "https://schema.org",
  "@type": "SoftwareApplication",
  name: "ProGran: Programme Analytics & Monitoring",
  url: "https://www.relific.io/progran",
  applicationCategory: "BusinessApplication",
  operatingSystem: "Web",
  description:
    "Monitor programmes with precision. ProGran connects your Theory of Change to real-world data for KPI tracking, predictive insights, and reporting.",
  creator: {
    "@type": "Organization",
    name: "Relific",
    url: "https://www.relific.io",
  },
};

const productSchema = {
  "@context": "https://schema.org",
  "@type": "Product",
  name: "ProGran: Programme Analytics & Monitoring",
  description:
    "ProGran is an enterprise-grade programme monitoring and evaluation platform that links your Theory of Change to ground truth data. Track KPIs, generate donor-ready reports, and get predictive insights across your entire programme portfolio.",
  brand: {
    "@type": "Brand",
    name: "Relific",
  },
  category: "Programme Analytics, SaaS Platform",
  image: "https://www.relific.io/logo.png",
  url: "https://www.relific.io/progran",
  offers: {
    "@type": "Offer",
    url: "https://www.relific.io/progran",
  },
};

const ProGranPage = () => {
  useEffect(() => {
    // Update document title and meta tags
    document.title =
      "ProGran: AI-Powered Programme Monitoring & Evaluation Platform";

    // Update or create meta tags
    const updateMeta = (name: string, content: string, property?: boolean) => {
      const selector = property
        ? `meta[property="${name}"]`
        : `meta[name="${name}"]`;
      let meta = document.querySelector(selector) as HTMLMetaElement;
      if (!meta) {
        meta = document.createElement("meta");
        if (property) {
          meta.setAttribute("property", name);
        } else {
          meta.setAttribute("name", name);
        }
        document.head.appendChild(meta);
      }
      meta.setAttribute("content", content);
    };

    // Update or create canonical link
    const updateCanonical = (href: string) => {
      let canonical = document.querySelector(
        'link[rel="canonical"]'
      ) as HTMLLinkElement;
      if (!canonical) {
        canonical = document.createElement("link");
        canonical.setAttribute("rel", "canonical");
        document.head.appendChild(canonical);
      }
      canonical.setAttribute("href", href);
    };

    // Set ProGran specific metadata
    updateMeta(
      "description",
      "Monitor programmes with precision. ProGran connects your Theory of Change to real-world data for KPI tracking, predictive insights, and reporting."
    );
    updateMeta("robots", "index, follow");
    updateCanonical("https://www.relific.io/progran");

    // Open Graph
    updateMeta(
      "og:title",
      "ProGran: AI-Powered Programme Monitoring & Evaluation Platform",
      true
    );
    updateMeta(
      "og:description",
      "Monitor programmes with precision. ProGran connects your Theory of Change to real-world data for KPI tracking, predictive insights, and reporting.",
      true
    );
    updateMeta("og:url", "https://www.relific.io/progran", true);
    updateMeta("og:type", "website", true);
    updateMeta("og:image", "https://relific.io/images/og-image.jpg", true);
    updateMeta("og:image:alt", "ProGran Programme Monitoring Platform", true);
    updateMeta("og:site_name", "Relific", true);

    // Twitter
    updateMeta("twitter:card", "summary_large_image");
    updateMeta(
      "twitter:title",
      "ProGran: AI-Powered Programme Monitoring & Evaluation Platform"
    );
    updateMeta(
      "twitter:description",
      "Monitor programmes with precision. ProGran connects your Theory of Change to real-world data for KPI tracking, predictive insights, and reporting."
    );
    updateMeta("twitter:image", "https://relific.io/images/og-image.jpg");
  }, []);

  return (
    <>
      <Script
        id="software-application-schema"
        type="application/ld+json"
        strategy="beforeInteractive"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify(softwareApplicationSchema),
        }}
      />
      <Script
        id="product-schema"
        type="application/ld+json"
        strategy="beforeInteractive"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify(productSchema),
        }}
      />
      <ProGran />
    </>
  );
};

export default ProGranPage;
